<script setup>
import { computed,ref } from 'vue'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
const store=useDemo(),search=ref(''),mine=ref(false)
const rows=computed(()=>store.selectEvents({search:search.value}).filter(e=>!mine.value || e.investigatorId===store.currentUser.value?.id).map(e=>({...e,reports:store.visibleRecords('reports').filter(r=>r.eventId===e.id),investigator:store.state.users.find(u=>u.id===e.investigatorId)?.name || 'Unassigned'})))
const columns=[{name:'ref',label:'Incident',field:'ref',align:'left',sortable:true},{name:'investigator',label:'Investigator',field:'investigator',align:'left',sortable:true},{name:'stage',label:'Report stage / revisions',field:'reports',align:'left'},{name:'asOf',label:'Latest as-of / target',field:'reports',align:'left'},{name:'status',label:'Review status',field:'status',align:'left'},{name:'actions',label:'',field:'id'}]
</script>
<template><div class="page-wrap"><PageHeader title="Investigations" subtitle="Assign an investigator and maintain separate initial, progress and final report revisions."/><div class="panel toolbar-row q-mb-md"><q-input v-model="search" outlined dense clearable label="Search incident or vessel" style="min-width:260px"><template #prepend><q-icon name="search"/></template></q-input><q-toggle v-model="mine" label="Assigned to me"/><q-space/><span class="muted">{{rows.length}} incidents</span></div><div class="panel"><q-table flat :rows="rows" :columns="columns" row-key="id" :pagination="{rowsPerPage:10}"><template #body-cell-ref="p"><q-td :props="p"><router-link class="record-link" :to="`/admin/investigations/${p.row.id}`">{{p.row.ref}}</router-link><div class="muted">{{p.row.type}} · {{p.row.date || 'Date unknown'}}</div></q-td></template><template #body-cell-stage="p"><q-td :props="p"><div v-if="p.row.reports.length"><q-chip v-for="type in ['1B','2','3B']" :key="type" dense square :color="p.row.reports.some(r=>r.type===type && r.status==='issued')?'green-1':'grey-3'" text-color="dark">{{type}} · {{p.row.reports.filter(r=>r.type===type).length}}</q-chip></div><span v-else class="muted">Investigation not started</span></q-td></template><template #body-cell-asOf="p"><q-td :props="p">{{p.row.reports.map(r=>r.asOf || r.date).filter(Boolean).sort().reverse()[0] || 'Not reported'}}<div class="muted">Target {{p.row.reports.find(r=>r.fields?.investigationDueDate)?.fields.investigationDueDate || 'not assigned'}}</div></q-td></template><template #body-cell-status="p"><q-td :props="p"><StatusBadge :status="p.row.status"/></q-td></template><template #body-cell-actions="p"><q-td :props="p"><q-btn color="primary" flat no-caps label="Workbench" :to="`/admin/investigations/${p.row.id}`"/></q-td></template></q-table></div></div></template>
